 doc=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=1440"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#0b090a"><title>{html.escape(title)} | VECTA</title><link rel="icon" href="/favicon.svg"><link rel="preload" as="font" type="font/woff2" href="/fonts/prata-editorial.woff2" crossorigin><link rel="stylesheet" href="/design.css"><link rel="stylesheet" href="/desktop-review.css"><link rel="stylesheet" href="/editorial-desktop.css"><link rel="stylesheet" href="/editorial-system.css"></head><body id="top" class="editorial-v3{' surface-paper' if file in ('request.html','formats.html') else ''}"><a class="skip" href="#main">К содержанию</a><header class="header"><a href="/" class="brand" aria-label="VECTA Weddings — главная">VECTA</a><nav aria-label="Основная навигация">{links}</nav><button class="menu" aria-label="Открыть меню" aria-expanded="false" aria-controls="mobile-nav">Меню +</button></header><nav class="mobile-nav" id="mobile-nav" hidden aria-label="Мобильная навигация">{links}</nav><main id="main">{body}</main>{footer}<script src="/design.js" defer></script></body></html>'''
